def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def stop(msg):
    print("STOP:", msg)
    raise SystemExit(2)

def restore(backup, existed):
    print()
    print("===== RESTORE =====")
    for rel in TARGETS:
        target = ROOT / rel
        src = backup / rel
        if existed.get(rel):
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, target)
        elif target.exists():
            target.unlink()
    print("RESTORE: PASS")

def run(cmd, label):
    print()
    print("===== " + label + " =====")
    result = subprocess.run(cmd, cwd=ROOT, text=True)
    if result.returncode != 0:
        raise RuntimeError(label + " failed")

